                                  <option value="multiple">Multiple Choice (Multi)</option>
                                  <option value="truefalse">True / False</option>
                                  <option value="fillin">Fill in the Blank</option>
                                </select>
                              </div>

                              <div className="input-group">
                                <label style={{ color: 'var(--text-primary)', fontWeight: 600 }}>Correct Answer</label>
                                {q.type === 'truefalse' ? (
                                  <select className="input-field" value={q.correctAnswer} onChange={(e) => updateQuestion(i, 'correctAnswer', e.target.value)}>
                                    <option value="">Select...</option>
                                    <option>True</option>
                                    <option>False</option>
                                  </select>
                                ) : (
                                  <input className="input-field" value={q.correctAnswer} placeholder={q.type === 'multiple' ? 'Comma-separated: Option1,Option2' : 'Correct answer'} onChange={(e) => updateQuestion(i, 'correctAnswer', e.target.value)} />
                                )}
                              </div>
                            </div>

                            {q.type !== 'truefalse' && q.type !== 'fillin' && (
                              <div className="input-group" style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                                <label style={{ color: 'var(--text-primary)', fontWeight: 600 }}>Options</label>
                                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '0.75rem' }}>
                                  {q.options.map((opt, oi) => (
                                    <div key={oi} style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                                      <span style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>Option {oi + 1}</span>
                                      <input
                                        className="input-field"
                                        value={opt}
                                        placeholder={`Option ${oi + 1}`}
                                        onChange={(e) => updateOption(i, oi, e.target.value)}
                                      />
                                    </div>
                                  ))}
                                </div>
                              </div>
                            )}

                            <div className="input-group">
                              <label style={{ color: 'var(--text-primary)', fontWeight: 600 }}>Explanation (optional)</label>
                              <input className="input-field" value={q.explanation} onChange={(e) => updateQuestion(i, 'explanation', e.target.value)} />
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div style={{
                    padding: '1.25rem 2rem',
                    borderTop: '1px solid var(--glass-border)',
                    display: 'flex',
                    justifyContent: 'flex-end',
                    gap: 12,
                    background: 'rgba(10, 15, 25, 0.4)',
                    backdropFilter: 'blur(10px)',
                  }}>
                    <button type="button" className="btn btn-secondary" onClick={() => setShowQuizModal(false)}>Cancel</button>
                    <button type="submit" className="btn btn-primary" disabled={isLoading}>
                      {isLoading ? 'Saving...' : (editingQuiz ? 'Update Quiz' : 'Create Quiz')}
                    </button>
                  </div>
                </form>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </PageTransition>
  );
}

'use client';

import { motion } from 'framer-motion';
import { GraduationCap, Mail, BookOpen, Award } from 'lucide-react';
import { FadeInUp, PageTransition, StaggerContainer, StaggerItem } from '@/components/animations/MotionWrappers';
import styles from './page.module.css';
import { CourseWithArrays } from '@/lib/utils';
import { Student, Enrollment } from '@/generated/prisma/client';

export default function AdminStudentsClient({
  students,
  courses,
  enrollments
}: {
  students: Student[],
  courses: CourseWithArrays[],
  enrollments: Enrollment[]
}) {
  return (
    <PageTransition>
      <div className={styles.page}>
        <FadeInUp>
          <div className={styles.header}>
            <h1 className={styles.title}>Students</h1>
            <p className={styles.subtitle}>View enrolled students and their progress.</p>
          </div>
        </FadeInUp>

        <StaggerContainer className={styles.studentsGrid}>
          {students.map((student) => {
            const studentEnrollments = enrollments.filter((e) => e.studentId === student.id);
            const enrolledCoursesCount = studentEnrollments.length;
            const completedCoursesCount = studentEnrollments.filter(e => e.progress === 100).length;

            return (
              <StaggerItem key={student.id}>
                <motion.div
                  className={styles.studentCard}
                  whileHover={{ y: -4 }}
                  transition={{ type: 'spring', stiffness: 300, damping: 20 }}
                >
                  <div className={styles.studentAvatar}>{student.name.charAt(0)}</div>
                  <h3 className={styles.studentName}>{student.name}</h3>
                  <div className={styles.studentEmail}>
                    <Mail size={14} />
                    <span>{student.email}</span>
                  </div>
                  <div className={styles.studentStats}>
                    <div>
                      <BookOpen size={16} />
                      <strong>{enrolledCoursesCount}</strong>
                      <span>Enrolled</span>
                    </div>
                    <div>
                      <Award size={16} />
                      <strong>{completedCoursesCount}</strong>
                      <span>Completed</span>
                    </div>
                  </div>
                  <div className={styles.enrolledList}>
                    {studentEnrollments.map((enrollment) => {
                      const course = courses.find((c) => c.id === enrollment.courseId);
                      return (
                        <div key={enrollment.id} className={styles.enrolledItem}>
                          <span>
                            <img src={course?.logo} alt="" style={{ width: '1em', height: '1em', objectFit: 'contain', verticalAlign: 'middle', marginRight: '4px' }} /> {course?.title}
                          </span>
                          <div className={styles.progressBar}>
                            <motion.div
                              className={styles.progressFill}
                              initial={{ width: 0 }}
                              animate={{ width: `${enrollment.progress}%` }}
                              transition={{ duration: 1 }}
                            />
                          </div>
                          <span className={styles.progressText}>{enrollment.progress}%</span>
                        </div>
                      );
                    })}
                    {studentEnrollments.length === 0 && (
                      <p style={{ fontSize: '0.82rem', color: 'var(--text-tertiary)', textAlign: 'center' }}>
                        No courses enrolled yet.
                      </p>
                    )}
                  </div>
                </motion.div>
              </StaggerItem>
            );
          })}
        </StaggerContainer>

        {students.length === 0 && (
          <FadeInUp>
            <div style={{ textAlign: 'center', padding: '4rem 2rem', color: 'var(--text-secondary)' }}>
              <p>No students have registered yet.</p>
            </div>
          </FadeInUp>
        )}
      </div>
    </PageTransition>
  );
}

import { NextRequest, NextResponse } from 'next/server';
import {
  getCloudinary, ALLOWED_TYPES, MAX_FILE_SIZE,
  getResourceType, getFileTypeLabel,
} from '@/lib/cloudinary';
import { prisma } from '@/lib/prisma';

export const runtime = 'nodejs';

// ── GET /api/admin/files?lessonId=xxx ─────────────────────────────────────────
export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const lessonId = searchParams.get('lessonId');
  const courseId = searchParams.get('courseId');

  const where: Record<string, unknown> = {};
  if (lessonId) where.lessonId = lessonId;
  if (courseId) where.courseId = courseId;

  const files = await prisma.lessonFile.findMany({
    where,
    orderBy: { uploadedAt: 'desc' },
  });
  return NextResponse.json({ files });
}

// ── DELETE /api/admin/files ───────────────────────────────────────────────────
export async function DELETE(req: NextRequest) {
  try {
    const cld = getCloudinary();
    const { id } = await req.json();
    if (!id) return NextResponse.json({ error: 'id required' }, { status: 400 });

    const record = await prisma.lessonFile.findUnique({ where: { id } });
    if (!record) return NextResponse.json({ error: 'File not found' }, { status: 404 });

    await cld.uploader.destroy(record.publicId, {
      resource_type: getResourceType(record.mimeType),
    });
    await prisma.lessonFile.delete({ where: { id } });

    return NextResponse.json({ ok: true });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Delete failed.';
    console.error('[files delete]', err);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

// ── PATCH /api/admin/files — replace file or update metadata ──────────────────
export async function PATCH(req: NextRequest) {
  try {
    const cld  = getCloudinary();
    const form = await req.formData();

    const id          = form.get('id') as string;
    const title       = form.get('title') as string | null;
    const description = form.get('description') as string | null;
    const newFile     = form.get('file') as File | null;

    if (!id) return NextResponse.json({ error: 'id required' }, { status: 400 });

    const record = await prisma.lessonFile.findUnique({ where: { id } });
    if (!record) return NextResponse.json({ error: 'File not found' }, { status: 404 });

    let updateData: Record<string, unknown> = {};
    if (title       !== null) updateData.title       = title;
    if (description !== null) updateData.description = description;

    if (newFile) {
      if (!ALLOWED_TYPES.includes(newFile.type))
        return NextResponse.json({ error: `File type "${newFile.type}" not allowed.` }, { status: 400 });
      if (newFile.size > MAX_FILE_SIZE)
        return NextResponse.json({ error: 'File exceeds 200 MB limit.' }, { status: 400 });

      // Delete old asset from Cloudinary
      await cld.uploader.destroy(record.publicId, {
        resource_type: getResourceType(record.mimeType),
      });

      // Upload new asset
      const buffer       = Buffer.from(await newFile.arrayBuffer());
      const resourceType = getResourceType(newFile.type);
      const folder       = record.publicId.substring(0, record.publicId.lastIndexOf('/'));

      const uploadResult = await new Promise<{ secure_url: string; public_id: string }>(
        (resolve, reject) => {
          const stream = cld.uploader.upload_stream(
            { folder, resource_type: resourceType },
            (err, res) => { if (err || !res) reject(err); else resolve(res as any); },
          );
          stream.end(buffer);
        },
      );

      updateData = {
        ...updateData,
        secureUrl: uploadResult.secure_url,
        publicId:  uploadResult.public_id,
        fileType:  getFileTypeLabel(newFile.type),
        mimeType:  newFile.type,
        fileSize:  newFile.size,
      };
    }

    const updated = await prisma.lessonFile.update({ where: { id }, data: updateData });
    return NextResponse.json({ file: updated });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Update failed.';
    console.error('[files patch]', err);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getCloudinary, ALLOWED_TYPES, MAX_FILE_SIZE, getResourceType, getFileTypeLabel } from '@/lib/cloudinary';
import { prisma } from '@/lib/prisma';

export const runtime = 'nodejs';

export async function POST(req: NextRequest) {
  try {
    const cld = getCloudinary();
    const form = await req.formData();
    const file        = form.get('file') as File | null;
    const title       = (form.get('title') as string) || '';
    const description = (form.get('description') as string) || '';
    const lessonId    = (form.get('lessonId') as string) || null;
    const courseId    = (form.get('courseId') as string) || '';

    // ── Validation ────────────────────────────────────────────────
    if (!file) return NextResponse.json({ error: 'No file provided.' }, { status: 400 });
    if (!ALLOWED_TYPES.includes(file.type)) {
      return NextResponse.json({ error: `File type "${file.type}" is not allowed.` }, { status: 400 });
    }
    if (file.size > MAX_FILE_SIZE) {
      return NextResponse.json({ error: 'File exceeds the 200 MB size limit.' }, { status: 400 });
    }

    // ── Convert File → Buffer ─────────────────────────────────────
    const arrayBuffer = await file.arrayBuffer();
    const buffer      = Buffer.from(arrayBuffer);

    const resourceType = getResourceType(file.type);
    const folder       = `lms/${courseId || 'general'}/${lessonId || 'misc'}`;

    // ── Upload to Cloudinary ──────────────────────────────────────
    const uploadResult = await new Promise<any>((resolve, reject) => {
      const uploadStream = cld.uploader.upload_stream(
        {
          folder,
          resource_type: resourceType,
          // For raw files (PDF/DOCX/PPT), allow inline viewing in browser
          ...(resourceType === 'raw' ? { flags: 'attachment:false' } : {}),
        },
        (error, result) => {
          if (error) reject(error);
          else resolve(result);
        },
      );
      uploadStream.end(buffer);
    });

    // ── Save metadata to DB ───────────────────────────────────────
    const saved = await prisma.lessonFile.create({
      data: {
        title:       title || file.name,
        description,
        secureUrl:   uploadResult.secure_url,
        publicId:    uploadResult.public_id,
        fileType:    getFileTypeLabel(file.type),
        mimeType:    file.type,
        fileSize:    file.size,
        lessonId:    lessonId || null,
        courseId:    courseId || '',
      },
    });

    return NextResponse.json({ file: saved }, { status: 201 });
  } catch (err: any) {
    console.error('[upload]', err);
    return NextResponse.json(
      { error: err?.message || 'Upload failed.' },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getCloudinary, MAX_FILE_SIZE, getResourceType } from '@/lib/cloudinary';

export const runtime = 'nodejs';

const ASSIGNMENT_ALLOWED = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/zip',
  'application/x-zip-compressed',
];

function getAssignmentFileType(mimeType: string): string {
  if (mimeType === 'application/pdf') return 'pdf';
  if (mimeType.includes('word')) return 'docx';
  if (mimeType.includes('zip')) return 'zip';
  return 'file';
}

// ── GET /api/admin/lessons/assignments?lessonId=xxx ─────────────────────────
export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const lessonId = searchParams.get('lessonId');
  if (!lessonId) return NextResponse.json({ error: 'lessonId required' }, { status: 400 });

  const assignments = await prisma.lessonAssignment.findMany({
    where: { lessonId },
    orderBy: { createdAt: 'asc' },
  });
  return NextResponse.json({ assignments });
}

// ── POST /api/admin/lessons/assignments  (multipart/form-data) ──────────────
export async function POST(req: NextRequest) {
  try {
    const form = await req.formData();
    const file         = form.get('file') as File | null;
    const title        = (form.get('title') as string) || '';
    const description  = (form.get('description') as string) || '';
    const instructions = (form.get('instructions') as string) || '';
    const deadline     = (form.get('deadline') as string) || '';
    const maxMarks     = parseInt((form.get('maxMarks') as string) || '100', 10);
    const lessonId     = (form.get('lessonId') as string) || '';
    const courseId     = (form.get('courseId') as string) || '';

    if (!title?.trim()) return NextResponse.json({ error: 'Title is required.' }, { status: 400 });
    if (!lessonId) return NextResponse.json({ error: 'lessonId required.' }, { status: 400 });

    let secureUrl = '';
    let publicId  = '';
    let fileType  = '';
    let mimeType  = '';
    let fileSize  = 0;

    if (file) {
      if (!ASSIGNMENT_ALLOWED.includes(file.type)) {
        return NextResponse.json({ error: `File type "${file.type}" is not allowed for assignments.` }, { status: 400 });
      }
      if (file.size > MAX_FILE_SIZE) {
        return NextResponse.json({ error: 'File exceeds the 200 MB size limit.' }, { status: 400 });
      }

      const cld = getCloudinary();
      const buffer = Buffer.from(await file.arrayBuffer());
      const folder = `GM-Training/Developers/Courses/Lessons/Assignments`;

      const uploadResult = await new Promise<any>((resolve, reject) => {
        const stream = cld.uploader.upload_stream(
          { folder, resource_type: getResourceType(file.type), use_filename: true, unique_filename: true },
          (error, result) => { if (error) reject(error); else resolve(result); },
        );
        stream.end(buffer);
      });

      secureUrl = uploadResult.secure_url;
      publicId  = uploadResult.public_id;
      fileType  = getAssignmentFileType(file.type);
      mimeType  = file.type;
      fileSize  = file.size;
    }

    const assignment = await prisma.lessonAssignment.create({
      data: {
        title: title.trim(),
        description,
        instructions,
        deadline: deadline ? new Date(deadline) : null,
        maxMarks: isNaN(maxMarks) ? 100 : maxMarks,
        secureUrl,
        publicId,
        fileType,
        mimeType,
        fileSize,
        lessonId,
        courseId,
      },
    });
    return NextResponse.json({ assignment }, { status: 201 });
  } catch (err: any) {
    console.error('[assignments post]', err);
    return NextResponse.json({ error: err?.message || 'Create failed.' }, { status: 500 });
  }
}

// ── PATCH /api/admin/lessons/assignments  (JSON — update metadata) ──────────
export async function PATCH(req: NextRequest) {
  try {
    const body = await req.json();
    const { id, title, description, instructions, deadline, maxMarks } = body;
    if (!id) return NextResponse.json({ error: 'id required' }, { status: 400 });

    const updated = await prisma.lessonAssignment.update({
      where: { id },
      data: {
        ...(title !== undefined && { title }),
        ...(description !== undefined && { description }),
        ...(instructions !== undefined && { instructions }),
        ...(deadline !== undefined && { deadline: deadline ? new Date(deadline) : null }),
        ...(maxMarks !== undefined && { maxMarks: Number(maxMarks) }),
      },
    });
    return NextResponse.json({ assignment: updated });
  } catch (err: any) {
    console.error('[assignments patch]', err);
    return NextResponse.json({ error: err?.message || 'Update failed.' }, { status: 500 });
  }
}

// ── DELETE /api/admin/lessons/assignments ────────────────────────────────────
export async function DELETE(req: NextRequest) {
  try {
    const { id } = await req.json();
    if (!id) return NextResponse.json({ error: 'id required' }, { status: 400 });

    const record = await prisma.lessonAssignment.findUnique({ where: { id } });
    if (!record) return NextResponse.json({ error: 'Assignment not found' }, { status: 404 });

    // Remove PDF from Cloudinary if uploaded
    if (record.publicId) {
      try {
        const cld = getCloudinary();
        await cld.uploader.destroy(record.publicId, { resource_type: getResourceType(record.mimeType) });
      } catch {
        // Non-fatal if Cloudinary cleanup fails
      }
    }
    await prisma.lessonAssignment.delete({ where: { id } });
    return NextResponse.json({ ok: true });
  } catch (err: any) {
    console.error('[assignments delete]', err);
    return NextResponse.json({ error: err?.message || 'Delete failed.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import {
  getCloudinary,
  MAX_FILE_SIZE,
  getResourceType,
} from '@/lib/cloudinary';

export const runtime = 'nodejs';

// Allowed MIME types for notes
const NOTES_ALLOWED_TYPES = [
  'application/pdf',
  'application/vnd.ms-powerpoint',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/zip',
  'application/x-zip-compressed',
  'text/plain',
];

function getNoteFileTypeLabel(mimeType: string): string {
  if (mimeType === 'application/pdf') return 'pdf';
  if (mimeType.includes('powerpoint') || mimeType.includes('presentation')) return 'pptx';
  if (mimeType.includes('word')) return 'docx';
  if (mimeType.includes('zip')) return 'zip';
  if (mimeType === 'text/plain') return 'txt';
  return 'file';
}

// ── GET /api/admin/lessons/notes?lessonId=xxx ─────────────────────────────────
