'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

type Token = { text: string; color?: string };
type Line = Token[];

const lines: Line[] = [
  [
    { text: 'import ', color: 'var(--accent-tertiary)' },
    { text: '{ Determination } ', color: 'rgba(255, 255, 255, 0.9)' },
    { text: 'from ', color: 'var(--accent-tertiary)' },
    { text: "'@/mindset';", color: 'var(--accent-warning)' },
  ],
  [],
  [
    { text: 'const ', color: 'var(--accent-tertiary)' },
    { text: 'potential ', color: 'var(--accent-primary)' },
    { text: '= ', color: 'rgba(255, 255, 255, 0.7)' },
    { text: 'unlock', color: 'var(--accent-secondary)' },
    { text: '();', color: 'rgba(255, 255, 255, 0.7)' },
  ],
  [
    { text: 'const ', color: 'var(--accent-tertiary)' },
    { text: 'limits ', color: 'var(--accent-primary)' },
    { text: '= ', color: 'rgba(255, 255, 255, 0.7)' },
    { text: 'break', color: 'var(--accent-secondary)' },
    { text: '();', color: 'rgba(255, 255, 255, 0.7)' },
  ],
  [],
  [
    { text: 'while ', color: 'var(--accent-tertiary)' },
    { text: '(', color: 'rgba(255, 255, 255, 0.7)' },
    { text: 'journey', color: 'var(--accent-primary)' },
    { text: '.', color: 'rgba(255, 255, 255, 0.7)' },
    { text: 'isOngoing', color: 'var(--accent-secondary)' },
    { text: ') {', color: 'rgba(255, 255, 255, 0.7)' },
  ],
  [
    { text: '  skills.', color: 'var(--accent-primary)' },
    { text: 'upgrade', color: 'var(--accent-secondary)' },
    { text: '(', color: 'rgba(255, 255, 255, 0.7)' },
    { text: 'Infinity', color: 'var(--accent-warning)' },
    { text: ');', color: 'rgba(255, 255, 255, 0.7)' },
  ],
  [
    { text: '  knowledge.', color: 'var(--accent-primary)' },
    { text: 'expand', color: 'var(--accent-secondary)' },
    { text: '();', color: 'rgba(255, 255, 255, 0.7)' },
  ],
  [
    { text: '}', color: 'rgba(255, 255, 255, 0.7)' },
  ],
  [],
  [
    { text: 'export const ', color: 'var(--accent-tertiary)' },
    { text: 'legacy ', color: 'var(--accent-primary)' },
    { text: '= ', color: 'rgba(255, 255, 255, 0.7)' },
    { text: 'build', color: 'var(--accent-secondary)' },
    { text: '();', color: 'rgba(255, 255, 255, 0.7)' },
  ]
];

export default function CodeTypingAnimation() {
  const [displayedChars, setDisplayedChars] = useState(0);
  const [isTyping, setIsTyping] = useState(true);

  // Calculate total characters
  const totalChars = lines.reduce(
    (acc, line) => acc + line.reduce((lineAcc, token) => lineAcc + token.text.length, 0),
    0
  );

  useEffect(() => {
    let timeout: NodeJS.Timeout;

    if (isTyping && displayedChars < totalChars) {
      // Type next character
      timeout = setTimeout(() => {
        setDisplayedChars((prev) => prev + 1);
      }, Math.random() * 50 + 60); // Noticeably slower typing speed
    } else if (isTyping && displayedChars === totalChars) {
      // Pause at the end, then start deleting
      timeout = setTimeout(() => {
        setIsTyping(false);
      }, 4000);
    } else if (!isTyping && displayedChars > 0) {
      // Delete characters
      timeout = setTimeout(() => {
        setDisplayedChars((prev) => prev - 1); // Delete 1 char at a time for smoother, slower erasing
      }, 15); // Effectively half the original speed
    } else if (!isTyping && displayedChars <= 0) {
      setDisplayedChars(0);
      // Pause briefly before restarting
      timeout = setTimeout(() => {
        setIsTyping(true);
      }, 1000);
    }

    return () => clearTimeout(timeout);
  }, [displayedChars, isTyping, totalChars]);

  // Helper to get visible tokens based on current displayedChars
  const renderLines = () => {
    let charsRemaining = displayedChars;
    const result = [];

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const visibleTokens = [];

      for (let j = 0; j < line.length; j++) {
        const token = line[j];
        if (charsRemaining <= 0) break;

        let renderText = '';
        if (charsRemaining >= token.text.length) {
          renderText = token.text;
          charsRemaining -= token.text.length;
        } else {
          renderText = token.text.substring(0, charsRemaining);
          charsRemaining = 0;
        }

        // Render each character with a 3D pop animation
        const charElements = renderText.split('').map((char, charIdx) => {
          const isSpace = char === ' ';
          return (
            <motion.span
              key={`${i}-${j}-${charIdx}`}
              initial={{ opacity: 0, scale: 0.3, y: 15, rotateX: -90 }}
              animate={{ opacity: 1, scale: 1, y: 0, rotateX: 0 }}
              transition={{ type: 'spring', stiffness: 300, damping: 15 }}
              style={{ display: 'inline-block', whiteSpace: 'pre' }}
            >
              {isSpace ? ' ' : char}
            </motion.span>
          );
        });

        visibleTokens.push(
          <span key={j} style={{ color: token.color }}>
            {charElements}
          </span>
        );
      }

      if (visibleTokens.length > 0 || (line.length === 0 && charsRemaining > 0)) {
        result.push(
          <div key={i} style={{ whiteSpace: 'nowrap' }}>
            {visibleTokens}
            {/* Show blinking cursor on the active line */}
            {charsRemaining === 0 && (
              <motion.span
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ repeat: Infinity, duration: 0.8, ease: "linear" }}
                style={{
                  display: 'inline-block',
                  width: '8px',
                  height: '16px',
                  background: 'var(--accent-primary)',
                  marginLeft: '4px',
                  verticalAlign: 'middle',
                }}
              />
            )}
          </div>
        );
      } else {
        // Empty lines to maintain layout height (optional, but good for stability)
        result.push(<div key={i} style={{ height: '24px' }}></div>);
      }
    }

    // Always ensure we have enough lines rendered to prevent the card height from collapsing
    while (result.length < 11) {
        result.push(<div key={`empty-${result.length}`} style={{ height: '24px' }}></div>);
    }

    // Add cursor to line 0 if completely empty
    if (displayedChars === 0) {
        result[0] = (
          <div key="0" style={{ whiteSpace: 'nowrap', height: '24px' }}>
            <motion.span
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ repeat: Infinity, duration: 0.8, ease: "linear" }}
                style={{
                  display: 'inline-block',
                  width: '8px',
                  height: '16px',
                  background: 'var(--accent-primary)',
                  marginLeft: '4px',
                  verticalAlign: 'middle',
                }}
              />
          </div>
        )
    }

    return result;
  };

  return (
    <div style={{ perspective: '1000px', fontSize: '0.9rem' }}>
      {renderLines()}
    </div>
  );
}

'use client';

import { motion } from 'framer-motion';
import {
  Star, Users, BookOpen, Award, BadgeCheck,
  ArrowRight, ShieldCheck, Trophy, Zap,
} from 'lucide-react';
import Link from 'next/link';
import { Trainer } from '@/generated/prisma/client';
import styles from './TrainerCard.module.css';

type Course = { id: string; title: string; logo: string; trainerId: string };

// ── SKILL DETECTION ──────────────────────────────────────────────────────────
const SKILL_MAP: { keyword: string; label: string; icon: string }[] = [
  { keyword: 'python',      label: 'Python',       icon: '🐍' },
  { keyword: 'react',       label: 'React',        icon: '⚛️' },
  { keyword: 'node',        label: 'Node.js',      icon: '🟢' },
  { keyword: 'java',        label: 'Java',         icon: '☕' },
  { keyword: 'javascript',  label: 'JavaScript',   icon: '🟡' },
  { keyword: 'typescript',  label: 'TypeScript',   icon: '🔷' },
  { keyword: 'django',      label: 'Django',       icon: '🎸' },
  { keyword: 'flask',       label: 'Flask',        icon: '🧪' },
  { keyword: 'spring',      label: 'Spring Boot',  icon: '🍃' },
  { keyword: 'angular',     label: 'Angular',      icon: '🔴' },
  { keyword: 'vue',         label: 'Vue',          icon: '💚' },
  { keyword: 'machine learning', label: 'ML',      icon: '🤖' },
  { keyword: 'data science', label: 'Data Science',icon: '📊' },
  { keyword: 'aws',         label: 'AWS',          icon: '☁️' },
  { keyword: 'docker',      label: 'Docker',       icon: '🐳' },
  { keyword: 'postgresql',  label: 'PostgreSQL',   icon: '🐘' },
  { keyword: 'mongodb',     label: 'MongoDB',      icon: '🍃' },
  { keyword: 'figma',       label: 'Figma',        icon: '🎨' },
  { keyword: 'ui/ux',       label: 'UI/UX',        icon: '✏️' },
  { keyword: 'c++',         label: 'C++',          icon: '⚙️' },
  { keyword: 'devops',      label: 'DevOps',       icon: '🔧' },
  { keyword: 'next',        label: 'Next.js',      icon: '▲' },
  { keyword: 'express',     label: 'Express',      icon: '🚀' },
  { keyword: 'rest api',    label: 'REST API',     icon: '🔗' },
  { keyword: 'full stack',  label: 'Full Stack',   icon: '💻' },
  { keyword: 'frontend',    label: 'Frontend',     icon: '🖥️' },
  { keyword: 'backend',     label: 'Backend',      icon: '⚙️' },
];

function getSkills(trainer: Trainer) {
  const text = `${trainer.specialization} ${trainer.bio}`.toLowerCase();
  return SKILL_MAP.filter((s) => text.includes(s.keyword)).slice(0, 6);
}

// ── TRUST INDICATORS ─────────────────────────────────────────────────────────
function getTrustBadges(trainer: Trainer): { icon: string; label: string }[] {
  const text = `${trainer.specialization} ${trainer.bio} ${trainer.experience}`.toLowerCase();
  const badges: { icon: string; label: string }[] = [];
  if (text.includes('google'))    badges.push({ icon: '🎓', label: 'Google Certified' });
  if (text.includes('aws'))       badges.push({ icon: '☁️', label: 'AWS Certified' });
  if (text.includes('microsoft')) badges.push({ icon: '🪟', label: 'Microsoft Certified' });
  if ((trainer.rating || 0) >= 4.8) badges.push({ icon: '⭐', label: 'Top Rated Mentor' });
  const students = (trainer.name.charCodeAt(0) * 47) % 500 + 50;
  if (students >= 300) badges.push({ icon: '👥', label: `${students}+ Students Trained` });
  return badges.slice(0, 3);
}

// ── FEATURED BADGE ───────────────────────────────────────────────────────────
function getFeaturedBadge(trainer: Trainer): { icon: string; label: string } | null {
  if ((trainer.rating || 0) >= 4.9) return { icon: '⭐', label: 'Top Rated' };
  if ((trainer.name.charCodeAt(0) * 47) % 500 + 50 >= 400) return { icon: '🏆', label: 'Featured' };
  return null;
}

// ── AVATAR GRADIENT — purple/blue palette only ──────────────────────────────
const GRADIENTS = [
  ['#4f46e5', '#818cf8'],   // indigo → light indigo
  ['#6366f1', '#a5b4fc'],   // violet → periwinkle
  ['#3b82f6', '#93c5fd'],   // blue → light blue
  ['#4f46e5', '#38bdf8'],   // indigo → sky
  ['#6366f1', '#67e8f9'],   // violet → cyan
  ['#3730a3', '#818cf8'],   // deep indigo → light indigo
  ['#1d4ed8', '#60a5fa'],   // deep blue → blue
];
function getGradient(name: string) {
  return GRADIENTS[name.charCodeAt(0) % GRADIENTS.length];
}

interface Props {
  trainer: Trainer;
  courses: Course[];
  isAdmin?: boolean;
  onEdit?: (trainer: Trainer) => void;
  onDelete?: (id: string) => void;
}

export default function TrainerCard({
  trainer, courses, isAdmin = false, onEdit, onDelete,
}: Props) {
  const trainerCourses = courses.filter((c) => c.trainerId === trainer.id);
  const skills        = getSkills(trainer);
  const trustBadges   = getTrustBadges(trainer);
  const featuredBadge = getFeaturedBadge(trainer);
  const [c1, c2]      = getGradient(trainer.name);
  const studentCount  = (trainer.name.charCodeAt(0) * 47) % 500 + 50;
  const MAX_COURSES   = 3;
  const extra         = trainerCourses.length - MAX_COURSES;

  return (
    <motion.div
      className={styles.card}
      whileHover={{ y: -8 }}
      transition={{ type: 'spring', stiffness: 280, damping: 22 }}
    >
      {/* ── MESH BACKGROUND ── */}
      <div className={styles.meshBg} />
      <div className={styles.gridPattern} />

      {/* ── TOP STRIPE ── */}
      <div className={styles.topStripe} style={{ background: `linear-gradient(90deg, ${c1}, ${c2})` }} />

      {/* ── FEATURED BADGE ── */}
      {featuredBadge && (
        <div className={styles.featuredBadge}
          style={{ background: `linear-gradient(135deg, ${c1}22, ${c2}22)`, borderColor: `${c1}44` }}>
          <span>{featuredBadge.icon}</span>
          <span>{featuredBadge.label}</span>
        </div>
      )}

      {/* ── ADMIN ACTIONS ── */}
      {isAdmin && (
        <div className={styles.adminActions}>
          <button className={styles.adminBtn} onClick={() => onEdit?.(trainer)} title="Edit">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/>
              <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/>
            </svg>
          </button>
          <button className={`${styles.adminBtn} ${styles.adminDanger}`} onClick={() => onDelete?.(trainer.id)} title="Delete">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
              <path d="M10 11v6M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>
            </svg>
          </button>
        </div>
      )}

      <div className={styles.inner}>
        {/* ── HEADER: AVATAR + INFO ── */}
        <div className={styles.header}>
          <div className={styles.avatarWrap}>
            {/* Radial glow behind avatar */}
            <div className={styles.avatarGlow} style={{ background: `radial-gradient(circle, ${c1}55 0%, transparent 70%)` }} />
            {trainer.avatar ? (
              <motion.img
                src={trainer.avatar} alt={trainer.name}
                className={styles.avatarImg}
                whileHover={{ scale: 1.05 }}
              />
            ) : (
              <motion.div
                className={styles.avatarInitials}
                style={{ background: `linear-gradient(135deg, ${c1}, ${c2})` }}
                whileHover={{ scale: 1.05 }}
              >
                {trainer.name.charAt(0).toUpperCase()}
              </motion.div>
            )}
            {/* Thin glowing ring */}
            <div className={styles.avatarRing} style={{ borderColor: `${c1}66` }} />
          </div>

          <div className={styles.nameBlock}>
            <div className={styles.nameRow}>
              <h3 className={styles.name}>{trainer.name}</h3>
              <BadgeCheck size={17} className={styles.verifiedIcon} />
            </div>
            <span className={styles.designation}>{trainer.specialization}</span>

            {/* Trust Indicators */}
            {trustBadges.length > 0 && (
              <div className={styles.trustRow}>
                {trustBadges.map((b) => (
                  <span key={b.label} className={styles.trustBadge}>
                    {b.icon} {b.label}
                  </span>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* ── STAT CARDS ── */}
        <div className={styles.statsGrid}>
          {[
            { icon: <Star size={18} />,     value: trainer.rating || '4.8',       label: 'Rating',   color: '#eab308' },
            { icon: <Users size={18} />,    value: studentCount,                   label: 'Students', color: '#60a5fa' },
            { icon: <BookOpen size={18} />, value: trainerCourses.length,          label: 'Courses',  color: '#818cf8' },
            { icon: <Award size={18} />,    value: trainer.experience || '5+',     label: 'Exp',      color: '#a5b4fc' },
          ].map((s) => (
            <motion.div
              key={s.label}
              className={styles.statCard}
              whileHover={{ y: -3, boxShadow: `0 8px 24px ${s.color}22` }}
              transition={{ type: 'spring', stiffness: 400, damping: 20 }}
            >
              <span className={styles.statIcon} style={{ color: s.color }}>{s.icon}</span>
              <span className={styles.statVal}>{s.value}</span>
              <span className={styles.statLbl}>{s.label}</span>
            </motion.div>
          ))}
        </div>

        {/* ── GRADIENT DIVIDER ── */}
        <div className={styles.gradDivider} style={{ background: `linear-gradient(90deg, transparent, ${c1}55, ${c2}44, transparent)` }} />

        {/* ── ABOUT ── */}
        <div className={styles.section}>
          <span className={styles.sectionLabel}>About Trainer</span>
          <p className={styles.bio}>
            {trainer.bio || 'Expert instructor with hands-on industry experience delivering practical, real-world training.'}
          </p>
        </div>

        {/* ── SKILLS ── */}
        {skills.length > 0 && (
          <div className={styles.section}>
            <span className={styles.sectionLabel}>Skills</span>
            <div className={styles.skillChips}>
              {skills.map((s) => (
                <motion.span
                  key={s.label}
                  className={styles.skillChip}
                  whileHover={{ scale: 1.04 }}
                  transition={{ type: 'spring', stiffness: 400, damping: 18 }}
                >
                  <span className={styles.skillIcon}>{s.icon}</span>
                  {s.label}
                </motion.span>
              ))}
            </div>
          </div>
        )}

        {/* ── COURSES ── */}
        <div className={styles.section}>
          <span className={styles.sectionLabel}>Courses</span>
          {trainerCourses.length === 0 ? (
            <span className={styles.noCourses}>No Courses Assigned</span>
          ) : (
            <div className={styles.courseChips}>
              {trainerCourses.slice(0, MAX_COURSES).map((c) => (
                <span key={c.id} className={styles.courseChip}>
                  <BookOpen size={11} style={{ flexShrink: 0, opacity: 0.6 }} />
                  {c.title}
                </span>
              ))}
              {extra > 0 && <span className={styles.moreChip}>+{extra} More</span>}
            </div>
          )}
        </div>

        {/* ── CTA ── */}
        <div className={styles.ctaWrap}>
          <Link href="/trainers" className={styles.ctaBtn}>
            <span>Explore Courses</span>
            <motion.span
              className={styles.ctaArrow}
              whileHover={{ x: 4 }}
              transition={{ type: 'spring', stiffness: 400, damping: 18 }}
            >
              <ArrowRight size={15} />
            </motion.span>
            {/* Shimmer overlay */}
            <span className={styles.ctaShimmer} />
          </Link>
        </div>
      </div>
    </motion.div>
  );
}

import { prisma } from '@/lib/prisma';
import { DEVELOPMENT_MODE } from '@/lib/config';

export interface ProgressionItem {
  type: 'lesson' | 'coding' | 'quiz';
  id: string; // lessonId, moduleId (for coding), quizId (for quiz)
  moduleId: string;
  title: string;
  url: string;
  problems?: any[];
  quizId?: string;
}

export function parseDurationToMinutes(durationStr: string): number {
  if (!durationStr) return 0;
  const match = durationStr.match(/(\d+)\s*(min|minute|hr|hour)/i);
  if (!match) {
    const num = parseInt(durationStr);
    return isNaN(num) ? 0 : num;
  }
  const val = parseInt(match[1]);
  const unit = match[2].toLowerCase();
  if (unit.startsWith('hr') || unit.startsWith('hour')) {
    return val * 60;
  }
  return val;
}

export async function getCourseProgression(courseId: string, studentId: string) {
  // Fetch modules and lessons
  const modules = await prisma.module.findMany({
    where: { courseId },
    orderBy: { order: 'asc' },
    include: { lessons: { orderBy: { order: 'asc' } } },
  });

  // Fetch coding problems for these lessons
  const lessonIds = modules.flatMap((m) => m.lessons.map((l) => l.id));
  const codingProblems = await prisma.codingProblem.findMany({
    where: { lessonId: { in: lessonIds } },
  });

  // Fetch quizzes for this course
  const quizzes = await prisma.quiz.findMany({
    where: { courseId },
  });

  // Fetch progress records
  const lessonProgress = await prisma.lessonProgress.findMany({
    where: { studentId, lessonId: { in: lessonIds } },
  });

  const quizAttempts = await prisma.quizAttempt.findMany({
    where: { studentId, quizId: { in: quizzes.map((q) => q.id) } },
  });

  const submissions = await prisma.codingSubmission.findMany({
    where: { studentId, problemId: { in: codingProblems.map((p) => p.id) } },
  });

  // Map progress statuses
  const completedLessonIds = new Set(lessonProgress.filter((p) => p.completed).map((p) => p.lessonId));
  const solvedProblemIds = new Set(submissions.filter((s) => s.status === 'success' || s.status === 'Accepted').map((s) => s.problemId));
  const passedQuizIds = new Set(quizAttempts.filter((q) => q.passed).map((q) => q.quizId));

  // Build sequential list of items
  const items: ProgressionItem[] = [];

  for (const mod of modules) {
    for (const les of mod.lessons) {
      items.push({
        type: 'lesson',
        id: les.id,
        moduleId: mod.id,
        title: les.title,
        url: `/learn/${courseId}/lesson/${les.id}`,
      });
    }

    const modProblems = codingProblems.filter((p) => p.lessonId && mod.lessons.some((l) => l.id === p.lessonId));
    if (modProblems.length > 0) {
      items.push({
        type: 'coding',
        id: mod.id, // Module ID represents this module's coding practice
        moduleId: mod.id,
        title: 'Coding Practice',
        url: `/practice/${modProblems[0].id}`, // point to first problem
        problems: modProblems,
      });
    }

    const modQuiz = quizzes.find((q) => q.moduleId === mod.id);
    if (modQuiz) {
      items.push({
        type: 'quiz',
        id: modQuiz.id,
        moduleId: mod.id,
        title: 'Module Quiz',
        url: `/learn/${courseId}/quiz/${modQuiz.id}`,
        quizId: modQuiz.id,
      });
    }
  }

  // Calculate completion and locked states
  const completedIds = new Set<string>();
  const lockedIds = new Set<string>();

  // If in development mode, skip locking logic entirely
  if (DEVELOPMENT_MODE) {
    // Populate completedIds as normal but keep lockedIds empty
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      let isCompleted = false;
      if (item.type === 'lesson') {
        isCompleted = completedLessonIds.has(item.id);
      } else if (item.type === 'coding') {
        isCompleted = item.problems?.every((p) => solvedProblemIds.has(p.id)) || false;
      } else if (item.type === 'quiz') {
        isCompleted = passedQuizIds.has(item.id);
      }
      if (isCompleted) completedIds.add(item.id);
    }
  } else {
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      
      // Check completion
      let isCompleted = false;
      if (item.type === 'lesson') {
        isCompleted = completedLessonIds.has(item.id);
      } else if (item.type === 'coding') {
        isCompleted = item.problems?.every((p) => solvedProblemIds.has(p.id)) || false;
      } else if (item.type === 'quiz') {
        isCompleted = passedQuizIds.has(item.id);
      }
      
      if (isCompleted) {
        completedIds.add(item.id);
      }

      // Check locking (first item is always unlocked)
      let isLocked = false;
      if (i > 0) {
        const prevItem = items[i - 1];
        let prevCompleted = false;
        if (prevItem.type === 'lesson') {
          prevCompleted = completedLessonIds.has(prevItem.id);
        } else if (prevItem.type === 'coding') {
          prevCompleted = prevItem.problems?.every((p) => solvedProblemIds.has(p.id)) || false;
        } else if (prevItem.type === 'quiz') {
          prevCompleted = passedQuizIds.has(prevItem.id);
        }
        
        // Locked if previous item was not completed or if previous item itself was locked
        isLocked = !prevCompleted || lockedIds.has(prevItem.id);
      }

      if (isLocked) {
        lockedIds.add(item.id);
      }
    }
  }

  return {
    items,
    completedIds,
    lockedIds,
    solvedProblemIds,
    completedLessonIds,
    passedQuizIds,
    modules,
    codingProblems,
    quizzes,
  };
}

export async function updateProgressInDb(courseId: string, studentId: string) {
  const { items, completedIds } = await getCourseProgression(courseId, studentId);

  const completedCount = completedIds.size;
  const totalCount = items.length;
  const percentage = totalCount > 0 ? (completedCount / totalCount) * 100 : 0;

  // Get last completed/visited lesson
  const lastLesson = items.filter((it) => it.type === 'lesson' && completedIds.has(it.id)).pop();

  await prisma.courseProgress.upsert({
    where: {
      studentId_courseId: {
        studentId,
        courseId,
      },
    },
    update: {
      completedLessons: completedCount,
      totalLessons: totalCount,
      percentage,
      lastLessonId: lastLesson?.id ?? '',
      isCompleted: completedCount === totalCount,
      completedAt: completedCount === totalCount ? new Date() : null,
    },
    create: {
      studentId,
      courseId,
      completedLessons: completedCount,
      totalLessons: totalCount,
      percentage,
      lastLessonId: lastLesson?.id ?? '',
      isCompleted: completedCount === totalCount,
      completedAt: completedCount === totalCount ? new Date() : null,
    },
  });

  // Sync to enrollment progress (integer 0-100)
  await prisma.enrollment.update({
    where: {
      studentId_courseId: {
        studentId,
        courseId,
      },
    },
    data: {
      progress: Math.round(percentage),
    },
  });
}

// src/services/practice/executionEngine.ts
import type { CodingProblem } from "@/generated/prisma/client";

export interface ExecutionResult {
  output: string;
  timeTaken: number; // in seconds
  memoryUsed: number; // in MB
  error?: string;
  status: "Accepted" | "Wrong Answer" | "Compilation Error" | "Runtime Error" | "Time Limit Exceeded" | "Memory Limit Exceeded";
}

export interface SubmissionResult {
  status: string;
  passedTests: number;
  totalTests: number;
  timeTaken: number;
  memoryUsed: number;
  score: number;
  output: string;
}

export interface TestCase {
  input: string;
  expected?: string;
  output?: string;
}

export abstract class Executor {
  abstract run(
    problem: CodingProblem,
    code: string,
    input: string,
    isStarterCode: boolean
  ): Promise<ExecutionResult>;
}

// Concrete implementation that simulates execution using expected outputs
export class MockExecutor extends Executor {
  async run(
    problem: CodingProblem,
    code: string,
    input: string,
    isStarterCode: boolean
  ): Promise<ExecutionResult> {
    // 1. Previously, starter code was treated as an error.
    // We now allow execution of starter code to let users test examples.
    // If code is empty, still return an error.
    if (!code.trim()) {
      return {
        output: "Error: No code provided. Please write your solution.",
        timeTaken: 0.05,
        memoryUsed: 12.4,
        error: "Wrong Answer",
        status: "Wrong Answer",
      };
    }

    // 2. Parse test cases
    let testCases: TestCase[] = [];
    try {
      const visible = JSON.parse(problem.visibleTests as string) as TestCase[];
      const hidden = JSON.parse(problem.hiddenTests as string) as TestCase[];
      testCases = [...visible, ...hidden];
    } catch (e) {
      console.error("Failed to parse test cases in MockExecutor:", e);
    }

    // 3. Find matching test case by input
    const normalizedInput = input.trim();
    const match = testCases.find(
      (tc) => tc.input.trim() === normalizedInput
    );

    if (match) {
      const expectedOutput = match.expected || match.output || "";
      return {
        output: expectedOutput,
        timeTaken: 0.12,
        memoryUsed: 15.6,
        status: "Accepted",
      };
    }

    // 4. Fallback: if no match, try to generate a dynamic response based on the problem title
    const title = problem.title.toLowerCase();
    let simulatedOutput = "";

    if (title.includes("hello world")) {
      simulatedOutput = "Hello, World!";
    } else if (title.includes("sum") || title.includes("add")) {
      // Try to sum numbers in input
      const nums = normalizedInput.split(/\s+/).map(Number).filter((n) => !isNaN(n));
      if (nums.length >= 2) {
        simulatedOutput = String(nums.reduce((sum, n) => sum + n, 0));
      } else {
        simulatedOutput = String(nums[0] ?? 0);
      }
    } else {
      simulatedOutput = `Simulation output for input "${input}"`;
    }

    return {
      output: simulatedOutput,
      timeTaken: 0.08,
      memoryUsed: 14.1,
      status: "Accepted",
    };
  }
}

// Registry of language executors
const mockExecutorInstance = new MockExecutor();

export const languageExecutors: Record<string, Executor> = {
  python: mockExecutorInstance,
  javascript: mockExecutorInstance,
  java: mockExecutorInstance,
  cpp: mockExecutorInstance,
  c: mockExecutorInstance,
};

export async function runCode(
  problem: CodingProblem,
  language: string,
  code: string,
  input: string
): Promise<ExecutionResult> {
  const executor = languageExecutors[language.toLowerCase()] || mockExecutorInstance;
  
  // Determine if code is unmodified starter code
  let isStarterCode = false;
  try {
    const starterMap = JSON.parse(problem.starterCode as string);
    const starter = starterMap[language] || "";
    isStarterCode = code.trim() === starter.trim();
  } catch {
    // Ignore parsing error
  }

  return executor.run(problem, code, input, isStarterCode);
}

export async function judgeSubmission(
  problem: CodingProblem,
  language: string,
  code: string
): Promise<SubmissionResult> {
  // Determine if starter code is unmodified
  let isStarterCode = false;
  try {
    const starterMap = JSON.parse(problem.starterCode as string);
    const starter = starterMap[language] || "";
    isStarterCode = code.trim() === starter.trim();
  } catch {
    // Ignore
  }

  // Parse hidden and visible test cases
  let hidden: TestCase[] = [];
  let visible: TestCase[] = [];
  try {
    hidden = JSON.parse(problem.hiddenTests as string) as TestCase[];
  } catch {}
  try {
    visible = JSON.parse(problem.visibleTests as string) as TestCase[];
  } catch {}

  const allTests = [...visible, ...hidden];
  const totalTests = allTests.length || 1; // At least 1 test case

  // Allow submissions with starter code; they will fail all tests but not be treated as a special error.
  if (!code.trim()) {
    return {
      status: "Wrong Answer",
      passedTests: 0,
      totalTests,
      timeTaken: 0.01,
      memoryUsed: 5.0,
      score: 0,
      output: "No code provided.",
    };
  }

  // Simulate execution of all test cases
  let passedTests = 0;
  const executor = languageExecutors[language.toLowerCase()] || mockExecutorInstance;

  for (const tc of allTests) {
    const res = await executor.run(problem, code, tc.input, false);
    if (res.status === "Accepted") {
      // Check output match
      const expected = (tc.expected || tc.output || "").trim();
      if (res.output.trim() === expected) {
        passedTests++;
      }
    }
  }

  // If there are no test cases in database, default to passed
  if (allTests.length === 0) {
    passedTests = 1;
  }

  const isAccepted = passedTests === totalTests;
  const status = isAccepted ? "Accepted" : "Wrong Answer";
  const ratio = passedTests / totalTests;
  const score = Math.round(problem.points * ratio);

  return {
    status,
    passedTests,
    totalTests,
    timeTaken: 0.15 * ratio,
    memoryUsed: 12.5,
    score,
    output: isAccepted
      ? "All test cases passed successfully!"
      : `${totalTests - passedTests} out of ${totalTests} test cases failed.`,
  };
}
